void ChemicalsSetupViewBase::buttonCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &BackButton)
    {
        //Back
        //When BackButton clicked change screen to HomeScreen
        //Go to HomeScreen with no screen transition
        application().gotoHomeScreenScreenNoTransition();
    }
    if (&src == &EnterButton)
    {
        //Enter
        //When EnterButton clicked call virtual function
        //Call EnterPressed
        EnterPressed();
    }
    if (&src == &ExitButton)
    {
        //Exit
        //When ExitButton clicked call virtual function
        //Call ExitPressed
        ExitPressed();
    }
    if (&src == &VolumeEdit1)
    {
        //TotalVolumeEdit
        //When VolumeEdit1 clicked execute C++ code
        //Execute C++ code
        presenter->editField(2);
    }
    if (&src == &NameEdit1)
    {
        //NameEdit
        //When NameEdit1 clicked execute C++ code
        //Execute C++ code
        presenter->editField(1);
    }
    if (&src == &AddPump1)
    {
        //AddPump
        //When AddPump1 clicked call virtual function
        //Call addPumpClicked
        addPumpClicked();
    }
    if (&src == &RemovePump1)
    {
        //RemovePump
        //When RemovePump1 clicked call virtual function
        //Call removePumpClicked
        removePumpClicked();
    }
    if (&src == &Chemical1EnableButton)
    {
        //Interaction1
        //When Chemical1EnableButton clicked call virtual function
        //Call chemicalEnableButtonClicked
        chemicalEnableButtonClicked();
    }
}
